print("state", p, "exists", p.exists())
for f in sorted(p.glob("*.jsonl")):
    print("jsonl", f.name)
# scan inbox for 12191
for name in ["youchu_ai_inbox.jsonl", "inbox.jsonl", "received.jsonl"]:
    fp = p / name
    if not fp.exists():
        # try nested
        for fp2 in p.rglob(name):
            fp = fp2; break
    if fp.exists():
        print("scan", fp)
        for line in fp.read_text(errors="ignore").splitlines()[-200:]:
            if "12191" in line or "12186" in line:
                try:
                    o=json.loads(line)
                except Exception:
                    print(line[:500]); continue
